def _clear_package_modules():
    # Prefer the embedded sources even if a startup customization imported an
    # installed version before this script ran. Changes affect this process only.
    for name in tuple(sys.modules):
        if name == "am_i_nerfed" or name.startswith("am_i_nerfed."):
            del sys.modules[name]


def main(argv=None):
    if sys.version_info < (3, 9):
        print("Am I Nerfed? requires Python 3.9 or newer.", file=sys.stderr)
        return 1
    try:
        payload = base64.b85decode(_PAYLOAD_B85)
    except (ValueError, TypeError):
        print("Standalone payload is invalid; obtain a fresh copy.", file=sys.stderr)
        return 1
    if hashlib.sha256(payload).hexdigest() != _PAYLOAD_SHA256:
        print("Standalone payload integrity check failed; obtain a fresh copy.", file=sys.stderr)
        return 1
    # TemporaryDirectory creates a private directory; the embedded ZIP is 0600.
    # Import straight from the ZIP without extracting files or installing code.
    with tempfile.TemporaryDirectory(prefix="am-i-nerfed-standalone-") as directory:
        archive = str(Path(directory) / "package.zip")
        fd = os.open(archive, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, "wb") as stream:
            stream.write(payload)
        _clear_package_modules()
        sys.path.insert(0, archive)
        try:
            from am_i_nerfed.cli import main as cli_main
            return cli_main(argv)
        finally:
            _clear_package_modules()
            try:
                sys.path.remove(archive)
            except ValueError:
                pass


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print("Interrupted; completed local evidence is retained.", file=sys.stderr)
        sys.exit(130)
